    with_parser(false, file, config_path, |p, _| {
        let program = p.parse_program()?.fold_with(&mut Normalizer {
            drop_span: false,
            is_test262: false,
        });

        let json = serde_json::to_string_pretty(&program).expect("failed to serialize as json");
